@@ -931,8 +932,31 @@ unsigned X86CgLowering::X86ChooseCmpOpcode(MVT VT) {
   }
 }

+// Logic instructions already set the flags of CMP(result, 0): CF=OF=0
+// and SF/ZF/PF come from the full-width result. Keep the produced value
+// cached; only omit the immediately redundant TEST, never recompute a tree.
+static bool hasZeroCompareFlags(const CgBasicBlock &BB, CgRegister Result,
+                                llvm::MVT VT) {
+  if (BB.empty() || (VT != MVT::i32 && VT != MVT::i64)) return false;
+  const auto &MI = BB.back();
+  if (!MI.getNumOperands() || !MI.getOperand(0).isReg() ||
+      !MI.getOperand(0).isDef() || MI.getOperand(0).getReg() != Result) return false;
+  switch (MI.getOpcode()) {
+  case X86::AND32rr: case X86::AND32ri: case X86::AND32ri8:
+  case X86::OR32rr: case X86::OR32ri: case X86::OR32ri8:
+  case X86::XOR32rr: case X86::XOR32ri: case X86::XOR32ri8:
+    return VT == MVT::i32;
+  case X86::AND64rr: case X86::AND64ri32: case X86::AND64ri8:
+  case X86::OR64rr: case X86::OR64ri32: case X86::OR64ri8:
+  case X86::XOR64rr: case X86::XOR64ri32: case X86::XOR64ri8:
+    return VT == MVT::i64;
+  default: return false;
+  }
+}
+
 void X86CgLowering::lowerFastCompareExpr(const MInstruction *LHS,
                                          const MInstruction *RHS, MVT VT) {
+  const bool Fresh = _expr_reg_map.find(LHS) == _expr_reg_map.end();
   CgRegister LHSReg = lowerExpr(*LHS);

   // We have two options: compare with register or immediate. If the RHS of the
@@ -946,6 +970,8 @@ void X86CgLowering::lowerFastCompareExpr(const MInstruction *LHS,
     const APInt &Value = ConstInt.getValue();
     int64_t Imm = Value.getSExtValue();
     if (Imm == 0) {
+      if (std::getenv("DTVM_RESEARCH_REUSE_LOGIC_FLAGS") && Fresh &&
+          hasZeroCompareFlags(*CurBB, LHSReg, VT)) return;
       unsigned TestOpc =
           LHS->getType()->isI32() ? X86::TEST32rr : X86::TEST64rr;
       fastEmitNoDefInst_rr(TestOpc, LHSReg, LHSReg);
@@ -1702,6 +1728,7 @@ void X86CgLowering::lowerBrIfStmt(const BrIfInstruction &Inst) {
   }

   if (!UsedCmpFlags) {
+    const bool Fresh = _expr_reg_map.find(Operand) == _expr_reg_map.end();
     CgRegister OperandReg = lowerExpr(*Operand);

     // Perform test instruction to determine whether the operand is zero.
@@ -1715,7 +1742,9 @@ void X86CgLowering::lowerBrIfStmt(const BrIfInstruction &Inst) {
     } else {
       TESTOpc = X86::TEST32rr;
     }
-    fastEmitNoDefInst_rr(TESTOpc, OperandReg, OperandReg);
+    if (!(std::getenv("DTVM_RESEARCH_REUSE_LOGIC_FLAGS") && Fresh &&
+          hasZeroCompareFlags(*CurBB, OperandReg, getMVT(*Operand->getType()))))
+      fastEmitNoDefInst_rr(TESTOpc, OperandReg, OperandReg);
     TakenCC = X86::COND_NE;
   }
